27: type GitEnv = Record<string, string> & {
28:    git_config_count?: string;
29: };
30: 
31: function* collectConfigByCount(env: GitEnv): Generator<ConfigWrite> {
32:    const count = parseInt(env.git_config_count ?? '0', 10);
33:    for (let index = 0; index < count; index++) {
34:       const key = env[`git_config_key_${index}`];
35:       const value = env[`git_config_value_${index}`];
36: 
37:       if (key !== undefined) {
38:          yield { key: key.toLowerCase().trim(), value, scope: 'env' };
39:       }
40:    }
41: }
42: 
43: function* collectConfigVulnerabilities(env: GitEnv): Generator<Vulnerability> {
44:    for (const key of Object.keys(env)) {
45:       if (isGitEnvKey(key)) {
46:          const category = GitEnvKeys[key];
47:          yield {
48:             category,
49:             message: `Use of "${key.toUpperCase()}" is not permitted without enabling ${category}`,
50:          };
51:       }
52:    }
53: }
54: 
55: function isGitEnvKey(key: string): key is keyof typeof GitEnvKeys {
56:    return Object.hasOwn(GitEnvKeys, key);
57: }
58: 
59: function prepareEnv(env: Record<string, unknown>): GitEnv {
60:    const gitEnv: GitEnv = {};
61:    for (const [key, value] of Object.entries(env)) {
62:       const envKey = key.toLowerCase().trim();
63:       if (isGitEnvKey(envKey) || envKey.startsWith('git')) {
64:          gitEnv[envKey] = String(value);
65:       }
66:    }
67:    return gitEnv;
68: }
69: 
70: export function parseEnv(raw: Record<string, unknown>) {
71:    const env = prepareEnv(raw);
72:    const config: ParsedConfigActivity = {
73:       read: [],
74:       write: [...collectConfigByCount(env)],
75:    };
76:    const vulnerabilities = [
77:       ...collectConfigVulnerabilities(env),
78:       ...vulnerabilityAnalysis(null, [], config),
79:    ];
80: 
81:    return {
82:       config,
83:       vulnerabilities,
84:    };
85: }
