203: async function stageDependencies(rootPkg: PackageJson): Promise<void> {
204:     const stagingPkg = buildStagingPackageJson(rootPkg);
205:     const workspacePkgs = discoverWorkspacePackages(rootPkg);
206: 
207:     // Rewrite workspace:* to exact versions; the mcpb build runs after the npm publish
208:     // (see publish.yml), so these resolve from the registry.
209:     const exactVersion = rootPkg.version;
210:     for (const ws of workspacePkgs) {
211:         const deps = stagingPkg.dependencies as Record<string, string> | undefined;
212:         const optDeps = stagingPkg.optionalDependencies as Record<string, string> | undefined;
213:         if (deps && ws.name in deps) {
214:             deps[ws.name] = exactVersion;
215:         }
216:         if (optDeps && ws.name in optDeps) {
217:             optDeps[ws.name] = exactVersion;
218:         }
219:     }
220: 
221:     await writeFile(resolve(paths.stagingDir, "package.json"), JSON.stringify(stagingPkg, null, 2) + "\n");
222: 
223:     // Seed the staging install with the root's lockfile/workspace yaml; the latter keeps
224:     // the staging dir its own workspace root so pnpm doesn't merge into the monorepo.
225:     await cp(resolve(paths.repoRoot, "pnpm-lock.yaml"), resolve(paths.stagingDir, "pnpm-lock.yaml"));
226:     await cp(resolve(paths.repoRoot, "pnpm-workspace.yaml"), resolve(paths.stagingDir, "pnpm-workspace.yaml"));
227: 
228:     // No --config.supported-architectures here: that would fan out cross-platform optional
229:     // deps (e.g. all four @oven/bun-linux-* variants on Linux runners). We only need the
230:     // host's optional deps for the install to succeed; the atlas-local platform binaries we
231:     // care about are listed as required deps in buildStagingPackageJson, so they install
232:     // unconditionally.
233:     await spawnAsync({
234:         cmd: "pnpm",
235:         args: ["install", "--prod", "--node-linker=hoisted", "--no-frozen-lockfile"],
236:         cwd: paths.stagingDir,
237:     });
238: 
239:     const stagedNodeModules = resolve(paths.stagingDir, "node_modules");
240: 
241:     // Strip @modelcontextprotocol/ext-apps's bundled dev tooling: Bun runtime binaries
242:     // (@oven/bun-*) and Rollup native bindings (@rollup/rollup-*). They land here because
243:     // ext-apps's optionalDependencies match the host platform, but the MCP server doesn't
244:     // use ext-apps's build pipeline at runtime. Each rm verifies the target really is a
245:     // platform-specific package (cpu/os constraints in its package.json) before deleting.
246:     const ovenDir = resolve(stagedNodeModules, "@oven");
247:     if (existsSync(ovenDir)) {
248:         const entries = readdirSync(ovenDir);
249:         await Promise.all(entries.map((entry) => rmIfPlatformSpecific(resolve(ovenDir, entry))));
250:     }
251:     const rollupDir = resolve(stagedNodeModules, "@rollup");
252:     if (existsSync(rollupDir)) {
253:         const entries = readdirSync(rollupDir);
254:         await Promise.all(
255:             entries
256:                 .filter((entry) => entry.startsWith("rollup-"))
257:                 .map((entry) => rmIfPlatformSpecific(resolve(rollupDir, entry)))
258:         );
259:     }
260: 
261:     // Kerberos isn't supported as the package is platform-specific and can't be installed for all platforms.
262:     const kerberosDir = resolve(stagedNodeModules, "kerberos");
263:     if (existsSync(kerberosDir)) {
264:         await rm(kerberosDir, { recursive: true, force: true });
265:     }
266: 
267:     // Replace the staging package.json with a minimal runtime one. Only `type: "module"`
268:     // affects Node's runtime behavior (ESM parsing for server/index.js).
269:     await writeFile(
270:         resolve(paths.stagingDir, "package.json"),
271:         JSON.stringify(
272:             {
273:                 name: "mongodb-mcp-server-mcpb",
274:                 version: rootPkg.version,
275:                 private: true,
276:                 type: "module",
277:             },
278:             null,
279:             2
280:         ) + "\n"
281:     );
282: }
