134: export function buildStagingPackageJson(rootPkg: PackageJson): PackageJson {
135:     const dependencies = { ...(rootPkg.dependencies ?? {}) } as Record<string, string>;
136:     const optionalDependencies = { ...(rootPkg.optionalDependencies ?? {}) } as Record<string, string>;
137: 
138:     const atlasLocalRange = dependencies["@mongodb-js/atlas-local"] ?? optionalDependencies["@mongodb-js/atlas-local"];
139:     if (!atlasLocalRange) {
140:         throw new Error("Expected @mongodb-js/atlas-local to be a (optional) dependency of the root package.");
141:     }
142:     // Strip semver range prefix; the platform packages publish exact versions matched to the parent.
143:     const exactVersion = atlasLocalRange.replace(/^[~^]/, "");
144:     for (const pkg of ATLAS_LOCAL_PLATFORM_PACKAGES) {
145:         dependencies[pkg] = exactVersion;
146:     }
147: 
148:     // Promote @mongodb-js/atlas-local from optional to required so the install can't silently
149:     // skip it. Without it, the platform binaries we just force-added are unreachable at runtime.
150:     dependencies["@mongodb-js/atlas-local"] = atlasLocalRange;
151:     delete optionalDependencies["@mongodb-js/atlas-local"];
