153:     return {
154:         name: "mongodb-mcp-server-mcpb-staging",
155:         version: rootPkg.version,
156:         private: true,
157:         type: "module",
158:         dependencies,
159:         optionalDependencies,
160:         // Carry the root's pnpm.overrides into the staging package so transitive resolution
161:         // stays aligned with what the root install (and CI) tested against. Without this,
162:         // pnpm's lockfile rewrite drops the overrides during the staging install.
163:         pnpm: (rootPkg as { pnpm?: Record<string, JsonValue> }).pnpm ?? {},
