50: function parseWorkspaceGlobs(yaml: string): string[] {
51:     // Simple parser: find a line starting with `packages:`, collect subsequent
52:     // `  - "..."` (or `  - '...'`) entries until the indentation changes.
53:     const lines = yaml.split(/\r?\n/);
54:     const globs: string[] = [];
55:     let inPackages = false;
56:     for (const raw of lines) {
57:         if (/^packages:\s*$/.test(raw)) {
58:             inPackages = true;
59:             continue;
60:         }
61:         if (inPackages) {
62:             const match = raw.match(/^\s*-\s*['"]?([^'"]+)['"]?\s*$/);
